import pyomo.environ as pyo

DATA = {
    "employees": ["X", "Y", "Z"],
    "cost": {"X": 8, "Y": 6, "Z": 5},
    "upper_bound": {"X": 10, "Y": 8, "Z": 6},
    "lower_bound": {"X": 0, "Y": 0, "Z": 0},
    "total_hours_cap": 24,
    "x_minus_y_min_gap": 2,
    "y_plus_z_cap": 16,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.employees = pyo.Set(initialize=d["employees"])

    def hours_bounds(m, e):
        return (d["lower_bound"][e], d["upper_bound"][e])

    model.hours = pyo.Var(
        model.employees,
        domain=pyo.NonNegativeIntegers,
        bounds=hours_bounds,
    )

    def obj_rule(m):
        return sum(d["cost"][e] * m.hours[e] for e in m.employees)

    model.obj = pyo.Objective(expr=obj_rule, sense=pyo.minimize)

    def total_hours_rule(m):
        return sum(m.hours[e] for e in m.employees) <= d["total_hours_cap"]

    model.total_hours_cap = pyo.Constraint(rule=total_hours_rule)

    def role_gap_rule(m):
        return m.hours["X"] - m.hours["Y"] >= d["x_minus_y_min_gap"]

    model.role_gap = pyo.Constraint(rule=role_gap_rule)

    def shared_workspace_rule(m):
        return m.hours["Y"] + m.hours["Z"] <= d["y_plus_z_cap"]

    model.shared_workspace = pyo.Constraint(rule=shared_workspace_rule)

    return model


